cd /tmp/world/filesystem; mm singlecell python - <<'EOF'
import openpyxl, pandas as pd
for f in ["mmc2.xlsx","mmc3.xlsx"]:
    wb = openpyxl.load_workbook(f, read_only=False)
    for ws in wb.worksheets:
        print(f, ws.title, "merged:", list(ws.merged_cells.ranges)[:20])
        cm = [(c.coordinate, c.comment.text) for r in ws.iter_rows() for c in r if c.comment]
        print("  comments:", cm[:20])
        # hidden rows/cols
        hid_r = [k for k,v in ws.row_dimensions.items() if v.hidden]
        hid_c = [k for k,v in ws.column_dimensions.items() if v.hidden]
        print("  hidden rows:", hid_r[:20], "hidden cols:", hid_c)
        # fills / colors  (highlighting)
        fills = {}
        for r in ws.iter_rows():
            for c in r:
                if c.fill is not None and c.fill.fgColor is not None and c.fill.fill_type:
                    fills.setdefault(str(c.fill.fgColor.rgb), []).append(c.coordinate)
        print("  fills:", {k: (len(v), v[:8]) for k,v in fills.items()})
        fonts = {}
        for r in ws.iter_rows():
            for c in r:
                if c.font is not None and (c.font.bold or (c.font.color is not None and c.font.color.rgb not in (None,'FF000000'))):
                    fonts.setdefault((c.font.bold, str(c.font.color.rgb) if c.font.color else None), []).append(c.coordinate)
        print("  fonts:", {k: (len(v), v[:8]) for k,v in fonts.items()})
    print(wb.properties)
EOF

